"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["5946"],{9831(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>d,frontMatter:()=>s,contentTitle:()=>r,toc:()=>l,assets:()=>c});var o=JSON.parse('{"id":"how-to/cloud/mqtt_howto","title":"How to use the MQTT Connector","description":"connectivity \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/how-to/cloud/mqtt_howto.md","sourceDirName":"how-to/cloud","slug":"/how-to/cloud/mqtt_howto","permalink":"/personal-av-docs/docs/how-to/cloud/mqtt_howto","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/how-to/cloud/mqtt_howto.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"How to use the MQTT Connector","sidebar_label":"How to use the MQTT Connector","sidebar_position":99,"edition":"connectivity","source":"https://doc.airvantage.net/connectivity/howto/cloud/mqtt_howto","format":"md"}}'),a=n(4848),i=n(8453);let s={title:"How to use the MQTT Connector",sidebar_label:"How to use the MQTT Connector",sidebar_position:99,edition:"connectivity",source:"https://doc.airvantage.net/connectivity/howto/cloud/mqtt_howto",format:"md"},r,c={},l=[];function u(e){let t={a:"a",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsxs)(t.p,{children:[":::note Edition\n",(0,a.jsx)(t.strong,{children:"connectivity"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,a.jsx)(t.a,{href:"https://doc.airvantage.net/connectivity/howto/cloud/mqtt_howto",children:"Original page"}),".\n:::"]}),"\n",(0,a.jsx)(t.p,{children:"How to use the MQTT Connector\nIntegrate and extend your AirVantage platform\nHere we give you an overview of what you can do with the AirVantage Cloud Connector via a simple use case: Connecting your system to\nMQTT Broker\nand getting raw data from your MQTT topic.\nWe\u2019ll explain all the technical aspects needed for a robust, secure & reliable interface:\nprinciples & best practices\nconfiguration & authentication\nhow to get messages\n1 /\nPrinciples\n2 /\nConfiguration\n3 /\nGet messages\nPrinciples\nThis section explains when and why to use the Cloud connector, what it is and the available options.\nIntroduction\nThe MQTT Cloud Connector provides:\nmessage notifications from AirVantage\nRouting mechanism\nRobust messaging for applications\nHigh volume messaging\nRuns on all major operating systems\nOpen source libraries for several common languages (java, c#, python, PHP, \u2026)\nParameters\nWhen you connect AirVantage to an MQTT broker, you have to define the type of notifications you want: operations, data, alert or usages.\nConfiguration\nThis section explains how to configure your client to be robust, reliable and secure. Please read carefully this section in order to supply correct information to enable the end point on the AirVantage side.\nWhat can I use?\nYou can use any MQTT broker like\nMosquitto\nor any broker embedded in a Cloud Platform like\ncloudMQTT\n.\nIn this tutorial, we will send messages to Mosquitto.\nPrerequisites\nMosquitto supplies a MQTT broker open to the community but they use it for tests.\nMQTT Broker Configuration\nSupply the following information using the\nCRM\nand select\nRequest Support\n:\nMQTT without SSL or with SSL\nUsername and password\nHostname and port number\nTopic where to publish messages\nKind of messages you want to receive:\nAlert event: any alert rule triggered will be send\nOperation: any operation state will be sent (creation, progress, success or failed)\nUsages: any SIM usage\nNew message sent by the device: any device incoming communication\nOptionnaly you can supply the data path to whitelist the data (only the values for these data will be sent in the data stream). To get the data path for a data, you can go to the timeline to view the data path in the tooltip like in the screenshot below:\nIn this tutorial, we use the following broker information:\nhostname: test.mosquitto.prg\nport: 1883 (or 8883)\nNo user or password\nA topic named\nanalytics\n)\nGet the messages\nThis section explains how to consume the messages from a MQTT Broker using MQTT Lens.\nStep 1.\nCreate a new connection in MQTTLens.\nStep 2.\nConfigure your connection to your MQTT Broker.\nFill the hostname and port number.\nClick on Create\nStep 3.\nSusbcribe to the topic (\nanalytics\nin this example)\nStep 4.\nIn AirVantage, push a data, generate an alert (based on the label creation condition) or create an operation according to what kind of message has been activated.\nStep 5.\nAccording to the messages the queue has subscribed to, you can:\nCreate a new\noperation\nby adding/removing a label on your system\nSend a data to AirVantage from your device in order to have new messages\nCreate a\nnew alert rule\nin Configure > Alert rules. You can raise an alert based on a new label added to your system, based on a new data value\nOpen and close a session using your SIM card\nYou can see your messages like in the screenshot on the right."})]})}function d(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(u,{...e})}):u(e)}},8453(e,t,n){n.d(t,{R:()=>s,x:()=>r});var o=n(6540);let a={},i=o.createContext(a);function s(e){let t=o.useContext(i);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),o.createElement(i.Provider,{value:t},e.children)}}}]);